+// API keys, role checks and the audit log of data-changing requests.
+import { AppError } from "../errors.js";
+
+const COOK_WRITES = [
+  /^\/recipes\/[^/]+\/cook$/,
+  /^\/batches\/[^/]+\/waste$/,
+  /^\/temperatures$/,
+  /^\/stocktakes\/[^/]+\/counts$/,
+];
+
+/** Finds the API key for an Authorization header, or throws unauthorized. */
+export function authenticate(store, header) {
+  const m = typeof header === "string" ? /^Bearer\s+(\S+)$/.exec(header.trim()) : null;
+  if (!m) throw new AppError("unauthorized");
+  const apiKey = (store.data.apiKeys ?? []).find((k) => k.key === m[1]);
+  if (!apiKey) throw new AppError("unauthorized");
+  return apiKey;
+}
+
+/** Verifies that `apiKey` has permission for `method` and `path`, or throws forbidden. */
+export function authorize(apiKey, method, path) {
+  if (apiKey.role === "manager") return;
+  if (method === "GET" && path !== "/audit" && (apiKey.role === "viewer" || apiKey.role === "cook")) return;
+  if (apiKey.role === "cook" && method === "POST" && COOK_WRITES.some((re) => re.test(path))) return;
+  throw new AppError("forbidden");
+}
+
+/** Appends an audit entry for a request that changed data and returns it. */
+export function recordAudit(store, { keyName, method, path, status }, { at }) {
+  store.data.audit ??= [];
+  const entry = { id: store.nextId("audit"), at, keyName, method, path, status };
+  store.data.audit.push(entry);
+  return entry;
+}
+
+/** Audit entries, newest first. */
+export function listAudit(store) {
+  return [...(store.data.audit ?? [])].sort((a, b) => b.at.localeCompare(a.at) || b.id - a.id);
+}
